            help: Some(self.help),
        });
        Ok(Published {
            report: self.report,
            ledger: self.ledger,
        })
    }
}
impl Published {
    pub(super) fn into_report(self) -> Vec<Diagnostic> {
        drop(self.ledger);
        self.report
    }
}

